const profileKeys=['name','company','incoterm','insurance','notes'];
const alertKeys=['booking','eta','exceptions','cost','market','important','tolerance','digest'];
let instructionDraft=null;
const operationExample='Priorize o prazo em cargas urgentes, mesmo que o frete não seja o mais barato.\nAntes de solicitar a coleta, confirme a prontidão da mercadoria com o fornecedor.\nAs entregas em Joinville precisam de agendamento e só podem ocorrer em dias úteis, das 8h às 16h.';
function operationState(){return state.operation??={instructions:'',rules:[]}}
function applySettings(form,keys){const f=new FormData(form);for(const key of keys)state.settings[key]=typeof seed.settings[key]==='boolean'?f.has(key):String(f.get(key)||'').trim()}
function profile(){
  const s=state.settings,o=operationState();
  heading('Perfil e operação','Conte como sua operação funciona. Transforme orientações em regras que você pode revisar.');
  $('#content').innerHTML=`<div class="profile-layout"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Orientações da sua operação</h2><p>O que o Centrix precisa saber para ajudar sua equipe a decidir?</p></div>${pill('IA · demonstração','purple')}</div><form id="instructions-form" class="pad"><label class="field">Descreva suas prioridades, restrições e formas de trabalhar<textarea id="operation-instructions" name="instructions" placeholder="Ex.: nas cargas urgentes, priorize o prazo. Antes da coleta, confirme a prontidão com o fornecedor…">${esc(instructionDraft??o.instructions)}</textarea></label><p class="small muted">Vale explicar como vocês escolhem frete, aprovam custos, coletam mercadorias e organizam entregas. Quanto mais concreto, melhor.</p><div class="actions detail-notes">${btn('Usar exemplo','instructions-example','',true)}<button type="submit" class="button secondary" name="intent" value="save">Salvar orientações</button><button type="submit" class="button" name="intent" value="suggest">Gerar sugestões de regras</button></div><p id="instructions-error" class="error" role="alert"></p><p class="small muted">Prévia sem IA conectada: o exemplo gera sugestões preparadas. Outros textos viram rascunhos para completar manualmente. Nenhuma regra é ativada automaticamente.</p></form></section><section class="panel"><div class="panel-head"><div><h2>Regras da operação</h2><p>Revise o contexto e o efeito de cada regra antes de ativá-la.</p></div><span class="small muted">${o.rules.filter(r=>r.status==='active').length} ativas na prévia</span></div><div class="pad">${o.rules.length?o.rules.map(r=>`<article class="operation-rule"><div class="rule-heading"><h3>${esc(r.title)}</h3>${pill(r.status==='review'?'A revisar':r.status==='active'?'Ativa na prévia':'Pausada',r.status==='active'?'green':r.status==='review'?'orange':'')}</div><small>${esc(r.scope)}</small><p><b>Quando:</b> ${esc(r.when||'Condição ainda não definida')}</p><p><b>Orientação:</b> ${esc(r.effect)}</p><details><summary>Ver orientação de origem</summary><p>${esc(r.source)}</p></details><div class="actions detail-notes">${btn(r.status==='review'?'Revisar sugestão':'Editar regra','rule-edit',r.id,true)}${r.status==='review'?btn('Descartar','rule-discard',r.id,true):btn(r.status==='active'?'Pausar':'Revisar e reativar',r.status==='active'?'rule-pause':'rule-edit',r.id,true)}</div></article>`).join(''):'<div class="empty"><h3>Sua operação ainda não tem regras</h3><p>Comece pelas orientações acima. As sugestões aparecem aqui para revisão.</p></div>'}</div></section></div><div class="stack"><form id="profile-form" class="stack"><section class="panel"><div class="panel-head"><h2>Seu perfil</h2></div><div class="pad fields">${field('Nome de exibição','name',s.name,'text',true)}${selectField('Empresa padrão','company',state.companies.map(c=>[c.id,c.name]),s.company)}</div></section><section class="panel"><div class="panel-head"><h2>Padrões da operação</h2></div><div class="pad fields">${selectField('Incoterm habitual','incoterm',['FOB','EXW','FCA','CIF','DAP'],s.incoterm)}${selectField('Seguro','insurance',['Avaliar em cada cotação','Solicitar na cotação'],s.insurance)}${textArea('Particularidades padrão','notes',s.notes)}<small class="field full">Padrões para preparar novas solicitações. Condições específicas precisam ser revisadas em cada caso.</small><button class="button secondary field full" type="submit">Salvar perfil e padrões</button></div></section></form>${note('<b>Você decide o que vira regra.</b><p>Na proposta, a IA organiza o texto e aponta o que precisa ser esclarecido. Sua equipe revisa e aprova.</p><p>Nesta prévia, ativar só altera o estado local. Não executa ações nem muda cotações e embarques.</p>')}<section class="panel"><div class="pad"><h3>Quer ajustar avisos?</h3><p>Tipos, sensibilidade e acompanhamento agora têm um lugar próprio.</p><p><a class="link" href="#alertas">Abrir Alertas →</a></p></div></section></div></div>`;
}
function alerts(){
  const s=state.settings;
  const sw=(key,title,desc)=>`<div class="setting-row"><div><strong>${title}</strong><small>${desc}</small></div><label class="switch"><input type="checkbox" name="${key}" aria-label="${title}" ${s[key]?'checked':''}><span></span></label></div>`;
  heading('Alertas','Escolha o que acompanhar e quando uma mudança merece sua atenção.');
  $('#content').innerHTML=`<div class="settings-grid"><form id="alerts-form" class="stack"><section class="panel"><div class="panel-head"><div><h2>Tipos de alerta</h2><p>Preferências pessoais de acompanhamento.</p></div></div><div class="pad">${sw('booking','Confirmações de embarque','Booking e marcos confirmados, conforme a fonte disponível.')}${sw('eta','Mudanças na chegada','Revisões de previsão com o local de chegada identificado.')}${sw('exceptions','Exceções e pendências','Documentos, aprovações e outros casos que pedem atenção.')}${sw('cost','Prazos e riscos de custo','Avisos quando houver prazo e condição comercial conhecidos.')}${sw('market','Oportunidades de preço','Sinais para avaliar uma cotação, separados da atenção operacional.')}</div></section><section class="panel"><div class="panel-head"><h2>Sensibilidade e acompanhamento</h2></div><div class="pad">${sw('important','Acompanhar cargas importantes de perto','Aplicar acompanhamento mais sensível às cargas marcadas por você.')}<div class="fields detail-notes">${selectField('Sensibilidade a mudanças de chegada','tolerance',['Qualquer mudança','A partir de 1 dia','A partir de 2 dias'],s.tolerance)}${selectField('Onde acompanhar','digest',['No portal'],s.digest)}</div><p class="small muted">Alertas dependem de eventos e fontes da operação. Nenhum envio é realizado nesta prévia.</p></div></section><div class="save-row"><button type="submit" class="button">Salvar alertas</button></div></form><aside class="settings-nav"><h3>Orientações da operação</h3><p>Prioridades, restrições e regras ficam em Perfil e operação. Aqui você escolhe como acompanhar as mudanças.</p><a class="link" href="#perfil">Abrir Perfil e operação</a></aside></div>`;
}
function draftRules(text){
  const prepared=[
    {title:'Prazo nas cargas urgentes',when:'Ao comparar propostas para uma carga identificada como urgente',effect:'Priorizar a avaliação de prazo. Exibir a diferença de custo para decisão, sem aprovar automaticamente.'},
    {title:'Prontidão antes da coleta',when:'Antes de solicitar a coleta de uma mercadoria',effect:'Solicitar confirmação de prontidão ao fornecedor e registrar a confirmação antes de avançar.'},
    {title:'Janela de entrega em Joinville',when:'Ao planejar uma entrega na unidade Joinville',effect:'Considerar dias úteis, das 8h às 16h, e exigir agendamento. Confirmar feriados e disponibilidade com a unidade.'}
  ];
  const isExample=text.trim()===operationExample;
  return (isExample?operationExample.split('\n'):text.split(/\n+/).map(s=>s.trim()).filter(Boolean)).map((source,n)=>({id:crypto.randomUUID(),title:isExample?prepared[n].title:`Orientação ${n+1}`,when:isExample?prepared[n].when:'',effect:isExample?prepared[n].effect:source,scope:'Operação da Aurora Indústria',source,status:'review',sourceText:text}));
}
function editRule(id){
  const r=operationState().rules.find(r=>r.id===id);if(!r)return;
  openDrawer('Revisar regra','Confirme quando a orientação se aplica e o que deve acontecer.',`<form id="rule-form" data-id="${id}"><div class="fields">${field('Nome da regra *','title',r.title,'text',true)}${field('Escopo *','scope',r.scope,'text',true)}<label class="field full">Quando se aplica *<textarea name="when" required placeholder="Descreva uma condição verificável">${esc(r.when)}</textarea></label><label class="field full">Orientação / efeito esperado *<textarea name="effect" required>${esc(r.effect)}</textarea></label></div><details class="detail-notes"><summary>Orientação original</summary><p>${esc(r.source)}</p></details>${note('Ativar nesta demonstração apenas salva a regra revisada. Avaliação de conflitos, permissões e execução dependem de integração futura.')}<p id="rule-error" role="alert" class="error"></p><div class="drawer-actions">${btn('Cancelar','close','',true)}<button type="submit" class="button">${r.status==='active'?'Salvar revisão':'Ativar na prévia'}</button></div></form>`);
}
document.addEventListener('submit',e=>{
  const form=e.target;
  if(['profile-form','alerts-form'].includes(form.id)){e.preventDefault();applySettings(form,form.id==='profile-form'?profileKeys:alertKeys);save();render();toast(form.id==='profile-form'?'Perfil e padrões salvos.':'Preferências de alertas salvas.');}
  if(form.id==='instructions-form'){
    e.preventDefault();const o=operationState(),text=new FormData(form).get('instructions').trim();
    if(e.submitter?.value==='suggest'&&!text){$('#instructions-error').textContent='Descreva sua operação ou use o exemplo para gerar sugestões.';return}
    o.instructions=text;instructionDraft=null;
    if(e.submitter?.value==='suggest'){
      const drafts=draftRules(text).filter(d=>!o.rules.some(r=>normalize(r.source)===normalize(d.source)));
      if(!drafts.length){save();toast('Estas orientações já têm regras. Revise as existentes para evitar duplicação.');return}
      o.rules.push(...drafts);
    }
    save();profile();toast(e.submitter?.value==='suggest'?'Sugestões preparadas para revisão. Nenhuma regra ativada.':'Orientações salvas. Regras existentes permanecem como estavam.');
  }
  if(form.id==='rule-form'){
    e.preventDefault();const r=operationState().rules.find(r=>r.id===form.dataset.id),f=new FormData(form);const values=Object.fromEntries([...f].map(([k,v])=>[k,v.trim()]));
    if(Object.values(values).some(v=>!v)){$('#rule-error').textContent='Complete nome, escopo, condição e orientação antes de ativar.';return}
    Object.assign(r,values,{status:'active'});save();closeDrawer();profile();toast('Regra revisada e ativa somente nesta prévia.');
  }
});
document.addEventListener('click',e=>{
  if(e.target.id==='confirm-reset')instructionDraft=null;
  const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset,o=operationState();
  if(action==='instructions-example'){const field=$('#operation-instructions');if(field.value.trim()){openDrawer('Usar exemplo','O texto atual ainda não foi substituído.',`<p>Trocar o texto do campo pelo exemplo demonstrativo? As regras já revisadas serão preservadas.</p><div class="drawer-actions">${btn('Cancelar','close','',true)}${btn('Substituir texto','confirm-example')}</div>`);}else{field.value=operationExample;instructionDraft=operationExample;field.focus();}}
  if(action==='confirm-example'){closeDrawer();$('#operation-instructions').value=operationExample;instructionDraft=operationExample;$('#operation-instructions').focus();}
  if(action==='rule-edit')editRule(id);
  if(action==='rule-pause'){o.rules.find(r=>r.id===id).status='paused';save();profile();toast('Regra pausada na prévia.');}
  if(action==='rule-discard'){o.rules=o.rules.filter(r=>r.id!==id);save();profile();toast('Sugestão descartada. A orientação original foi preservada.');}
});
document.addEventListener('input',e=>{if(e.target.id==='operation-instructions')instructionDraft=e.target.value});
